import test from 'node:test';import assert from './assert.mjs';import {JSDOM} from 'jsdom';import {act,createElement as h,createRef,StrictMode} from 'react';import {renderToString} from 'react-dom/server';import {userEvent} from '@testing-library/user-event';import {ResetPasswordBlock} from '@dmf-ui/react';import {ResetProof,renderReset} from '../.test-dist/server.mjs';
test('packed reset omits credential fields until ready, localizes statuses and preserves native form extensions',()=>{for(const state of ['unverified','invalid','expired']){const dom=new JSDOM(renderToString(h(ResetPasswordBlock,{id:'state',action:'/reset',credentialState:state,fields:h('input',{name:'scope'}),expiredMessage:'Tautan kedaluwarsa'})));try{assert.equal(dom.window.document.querySelector('input'),null);assert.equal(dom.window.document.querySelector('button'),null);if(state==='expired')assert(dom.window.document.querySelector('[role=status]').textContent.includes('Tautan'));}finally{dom.window.close();}}
 const dom=new JSDOM(renderToString(h(ResetPasswordBlock,{id:'ready',action:'/reset',credentialState:'ready',confirmPassword:true,passwordName:'newSecret',confirmPasswordName:'repeatSecret',passwordHelp:'Host policy',fieldErrors:{password:'Review policy'},fields:h('input',{name:'scope',defaultValue:'preview'})})));try{const f=dom.window.document.querySelector('form');assert.equal(f.method,'post');assert.equal(f.querySelectorAll('[autocomplete=new-password]').length,2);assert.equal(f.querySelector('[name=newSecret]').getAttribute('aria-describedby'),'ready-password-help ready-password-error');assert.equal(new dom.window.FormData(f).get('scope'),'preview');for(const el of f.querySelectorAll('[type=password]'))assert(!el.hasAttribute('value'));}finally{dom.window.close();}
 assert.throws(()=>renderToString(h(ResetPasswordBlock,{id:'bad',action:'/reset',credentialState:'unknown'})),/Unsupported/);assert.throws(()=>renderToString(h(ResetPasswordBlock,{id:'bad',action:'/reset',confirmPassword:true,confirmPasswordName:'password'})),/distinct/);
});
test('packed reset hydrates safely and host transitions clear fields, announce errors, focus status and preserve disabled independence',async()=>{const dom=new JSDOM(`<div id="root">${renderReset()}</div>`,{url:'https://consumer.test/reset.html'}),saved=new Map(),warnings=[];for(const key of ['window','document','HTMLElement','HTMLInputElement','navigator','FormData','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}let root;const old=console.error;console.error=(...args)=>warnings.push(args.join(' '));
 try{const {hydrateRoot}=await import('react-dom/client'),original=document.querySelector('#packed-reset-status');await act(async()=>{root=hydrateRoot(document.querySelector('#root'),h(StrictMode,{},h(ResetProof)),{identifierPrefix:'reset-',onRecoverableError:e=>warnings.push(String(e))});});assert(original===document.querySelector('#packed-reset-status'));assert.equal(document.querySelector('#packed-reset input'),null);const user=userEvent.setup({document}),press=async text=>act(async()=>user.click([...document.querySelectorAll('button')].find(b=>b.textContent===text)));
 await press('Show ready UI');let f=document.querySelector('#packed-reset');await act(async()=>user.click(f.querySelector('[type=submit]')));assert.equal(f.checkValidity(),false);await act(async()=>{await user.type(f.elements.namedItem('password'),'ephemeral-test');await user.type(f.elements.namedItem('confirmPassword'),'ephemeral-test');await user.click(f.querySelector('[type=submit]'));});assert(f.querySelector('fieldset').disabled);assert(document.querySelector('#packed-reset-disabled fieldset').disabled);await press('Show host error');assert(f.querySelector('[role=alert]'));assert.equal(f.elements.namedItem('password').getAttribute('aria-invalid'),'true');await press('Reset fields');assert.equal(f.elements.namedItem('password').value,'');await act(async()=>user.type(f.elements.namedItem('password'),'ephemeral-test'));await press('Show expired UI');assert.equal(f.querySelector('input'),null);assert(document.activeElement===document.querySelector('#packed-reset-status'));await press('Show ready UI');assert.equal(f.elements.namedItem('password').value,'');await press('Finish local preview');assert.equal(f.querySelector('input'),null);assert(document.activeElement===document.querySelector('#packed-reset-status'));assert.deepEqual(warnings,[]);
 }finally{if(root)await act(async()=>root.unmount());console.error=old;dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}});
test('bare packed reset forwards native refs, resets passwords and cleans up without a host singleton',async()=>{const dom=new JSDOM('<div id="root"></div>'),saved=new Map();for(const key of ['window','document','HTMLElement','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}let root;try{const {createRoot}=await import('react-dom/client'),ref=createRef();root=createRoot(document.querySelector('#root'));await act(async()=>root.render(h(ResetPasswordBlock,{id:'bare',action:'/reset',credentialState:'ready',ref})));ref.current.elements.namedItem('password').value='ephemeral-test';ref.current.reset();assert.equal(ref.current.elements.namedItem('password').value,'');assert.equal(ref.current.elements.namedItem('confirmPassword'),null);await act(async()=>root.unmount());root=null;assert.equal(ref.current,null);}finally{if(root)await act(async()=>root.unmount());dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}});
